INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(32811, 'Acts 7:16', 'Acts', 7, 16, 'د هغوی مړي شکیم ته یووړل شول او په هغې هدیره کې ښخ کړای شول چې ابراهیم د حمور د زامنو څخه په بیه اخیستې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_16.mp3', '', 1761754199, 1761754199),
(32812, 'Acts 7:17', 'Acts', 7, 17, 'کله چې هغه وخت راورسېد چې خدای د ابراهیم سره خپله کړې وعده پوره کړي، نو په دې وخت کې زمونږ د خلکو شمېر په مصر کې ډېر زیات شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_17.mp3', '', 1761754199, 1761754199),
(32813, 'Acts 7:18', 'Acts', 7, 18, 'بیا په مصر کې یو بل پاچا په تخت کښېناست چې یوسف یې نه پېژانده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_18.mp3', '', 1761754199, 1761754199),
(32814, 'Acts 7:19', 'Acts', 7, 19, 'هغه زمونږ د نیکونو سره ټګي وکړه، په هغوی باندې یې ظلم کاوه او هغوی یې دې ته مجبور کړل چې خپل نوي زېږېدلي ماشومان د کورونو څخه دباندې پرېږدي چې مړه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_19.mp3', '', 1761754199, 1761754199),
(32815, 'Acts 7:20', 'Acts', 7, 20, 'په دې وخت کې موسی وزېږېده. هغه یو ډېر ښکلی ماشوم ؤ او تر درې میاشتو پورې د هغه پالنه د خپل پلار په کور کې کېدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_20.mp3', '', 1761754199, 1761754199),
(32816, 'Acts 7:21', 'Acts', 7, 21, 'خو کله چې هغوی مجبور شول چې هغه د کور څخه دباندې پرېږدي، نو د فرعون لور هغه واخیست او د خپل زوی په شان یې د هغه روزنه کوله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_21.mp3', '', 1761754199, 1761754199),
(32817, 'Acts 7:22', 'Acts', 7, 22, 'موسی د مصریانو د ټول حکمت او پوهې تعلیم حاصل کړ. هغه په خبرو او کارونو کې غښتلی شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_22.mp3', '', 1761754199, 1761754199),
(32818, 'Acts 7:23', 'Acts', 7, 23, 'کله چې موسی څلوېښت کلن شو، نو په زړه کې یې دا وګرځېدل چې د خپلو اسراییلي ورونو د لیدلو دپاره لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_23.mp3', '', 1761754199, 1761754199),
(32819, 'Acts 7:24', 'Acts', 7, 24, 'کله چې هغه ولیدل چې یو مصري د یو اسراییلي سره بد چلند کاوه، نو هغه ورغی چې د هغه اسراییلي څخه دفاع وکړي او د مصري څخه یې د هغه بدل واخیست او هغه یې وواژه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_24.mp3', '', 1761754199, 1761754199),
(32820, 'Acts 7:25', 'Acts', 7, 25, 'موسی فکر کاوه چې د هغه خپل قوم به په دې پوه شي چې د ده په وسیله به خدای هغوی ته خلاصون ورکوي، خو هغوی پوه نه شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_25.mp3', '', 1761754199, 1761754199),
(32821, 'Acts 7:26', 'Acts', 7, 26, 'بله ورځ موسی ولیدل چې دوه اسراییلیانو په خپلو کې سره جګړه کوله او هغه هڅه کوله چې د هغوی ترمنځ روغه جوړه وکړي، نو موسی هغوی ته وویل: ‹ای خلکو! تاسو خو سره ورونه یئ، نو ولې یو د بله سره جګړه کوئ؟›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_26.mp3', '', 1761754199, 1761754199),
(32822, 'Acts 7:27', 'Acts', 7, 27, 'خو هغه ملامته سړي موسی ټېل واهه او ورته ویې ویل: ‹ته چا په مونږ باندې حاکم او قاضي ټاکلی یې؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_27.mp3', '', 1761754199, 1761754199),
(32823, 'Acts 7:28', 'Acts', 7, 28, 'ایا ته غواړې چې د پروني مصري په شان ما هم مړ کړې؟›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_28.mp3', '', 1761754199, 1761754199),
(32824, 'Acts 7:29', 'Acts', 7, 29, 'کله چې موسی دا خبره واورېدله، نو هغه د مصر څخه وتښتېد او مدیان ته لاړ او هلته د مسافر په شان اوسېده. هلته د هغه دوه زامن پیدا شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_29.mp3', '', 1761754199, 1761754199),
(32825, 'Acts 7:30', 'Acts', 7, 30, 'څلوېښت کاله وروسته د سینا غره ته نژدې په یوه دښته کې د یو سوځېدونکي بوټي د اور په لمبو کې یوه فرښته موسی ته ورښکاره شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_30.mp3', '', 1761754199, 1761754199),
(32826, 'Acts 7:31', 'Acts', 7, 31, 'کله چې موسی هغه ولیدله، نو حیران شو. څنګه چې نژدې ورغی چې هغه ښه وویني، نو د څښتن اواز یې واورېد:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_31.mp3', '', 1761754199, 1761754199),
(32827, 'Acts 7:32', 'Acts', 7, 32, '‹زه ستا د نیکونو خدای یم، د ابراهیم، اسحاق او یعقوب خدای یم.› موسی له وېرې رپېده او جرات یې نه شو کولای چې ورته وګوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_32.mp3', '', 1761754199, 1761754199),
(32828, 'Acts 7:33', 'Acts', 7, 33, 'څښتن هغه ته وویل: ‹خپلې څپلۍ وباسه، ځکه په کومه ځمکه باندې چې ته ولاړ یې هغه سپېڅلې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_33.mp3', '', 1761754199, 1761754199),
(32829, 'Acts 7:34', 'Acts', 7, 34, 'ما لیدلي دي چې زما په قوم باندې په مصر کې ظلم کیږي. ما د هغوی فریادونه اورېدلي او زه د هغوی د خلاصون دپاره راښکته شوی یم. اوس راشه، زه تا بېرته مصر ته لېږم.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_34.mp3', '', 1761754199, 1761754199),
(32830, 'Acts 7:35', 'Acts', 7, 35, 'نو دا هماغه موسی دی چې د اسراییلو خلکو رد کړی ؤ او ورته ویلي یې وو: ‹ته چا په مونږ باندې حاکم او قاضي ټاکلی یې؟› خدای همدا موسی د هغې فرښتې په وسیله چې هغه ته د سوځېدونکي بوټي د اور په لمبو کې ښکاره شوه، ولېږه ترڅو د اسراییلو د خلکو حاکم او خلاصوونکی وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_35.mp3', '', 1761754199, 1761754199),
(32831, 'Acts 7:36', 'Acts', 7, 36, 'دا موسی ؤ چې هغوی یې د مصر څخه راوویستل او په مصر او سره بحیره کې او څلوېښت کاله یې په دښته کې حیرانوونکي کارونه وکړل او معجزې یې وښودلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_36.mp3', '', 1761754199, 1761754199),
(32832, 'Acts 7:37', 'Acts', 7, 37, 'دا هغه موسی دی چې اسراییلیانو ته یې وویل: ‹خدای به ستاسو د خپل قوم څخه ستاسو دپاره زما په شان یو پیغمبر درولېږي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_37.mp3', '', 1761754199, 1761754199),
(32833, 'Acts 7:38', 'Acts', 7, 38, 'دا موسی ؤ چې په دښته کې زمونږ د نیکونو یعنې د خدای د قوم په غونډه کې د هغوی سره ؤ او فرښتې ورسره د سینا په غره کې خبرې وکړې. هلته هغه د خدای ژوندی کلام تر‌لاسه کړ چې مونږ ته یې راورسوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_38.mp3', '', 1761754199, 1761754199),
(32834, 'Acts 7:39', 'Acts', 7, 39, 'خو زمونږ نیکونو د موسی د منلو څخه انکار وکړ. هغه یې رد کړ او غوښتل یې چې بېرته مصر ته لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_39.mp3', '', 1761754199, 1761754199),
(32835, 'Acts 7:40', 'Acts', 7, 40, 'نو هغوی هارون ته وویل: ‹مونږ ته داسې خدایان جوړ کړه چې زمونږ لارښوونه وکړي. ځکه مونږ نه پوهېږو چې په دې موسی باندې چې مونږ یې له مصر څخه راوویستلو، څه وشول.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_40.mp3', '', 1761754199, 1761754199),
(32836, 'Acts 7:41', 'Acts', 7, 41, 'په هغه وخت کې هغوی د خوسکي په شکل یو بت جوړ کړ او هغه ته یې قرباني وړاندې کړه او په خپلو لاسونو جوړ شوي شي ته یې خوشحالي وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_41.mp3', '', 1761754199, 1761754199),
(32837, 'Acts 7:42', 'Acts', 7, 42, 'نو خدای د هغوی څخه مخ واړاوه او هغوی یې پرېښودل چې د اسماني ستورو عبادت وکړي، لکه څنګه چې د پیغمبرانو په کتابونو کې لیکل شوي دي: ای د اسراییلو قومه! ایا تاسو په دې څلوېښتو کالو کې په دې دښته کې ماته قربانۍ او نذرانې راوړې دي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_42.mp3', '', 1761754199, 1761754199),
(32838, 'Acts 7:43', 'Acts', 7, 43, 'نه، تاسو هغه د مولک بت د عبادت خېمه او د خپل رفان خدای د ستوري تصویر له ځان سره وړئ چې په خپله مو جوړ کړي دي چې عبادت یې وکړئ. نو تاسو به د بابل بلې خواته جلاوطنه کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_43.mp3', '', 1761754199, 1761754199),
(32839, 'Acts 7:44', 'Acts', 7, 44, 'زمونږ نیکونو په دښته کې د شهادت خېمه لرله. دا هغه خېمه وه چې خدای موسی ته حکم کړی ؤ چې د هغې نمونې له مخې چې هغه ته ښودل شوې وه، جوړه کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_44.mp3', '', 1761754199, 1761754199),
(32840, 'Acts 7:45', 'Acts', 7, 45, 'وروسته بیا دا خېمه زمونږ نیکونو ته ورکړل شوه او هغوی دا هغه وخت راوړله کله چې د یوشع سره روان وو او د هغو قومونو ځمکه یې ونیوله چې خدای د هغوی له مخې څخه لېرې کول. دا خېمه د داود تر وخته پورې هلته پاتې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_45.mp3', '', 1761754199, 1761754199),
(32841, 'Acts 7:46', 'Acts', 7, 46, 'خدای د داود څخه خوشحاله ؤ او هغه خدای ته سوال وکړ چې د یعقوب د خدای دپاره د اوسېدلو ځای جوړ کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_46.mp3', '', 1761754199, 1761754199),
(32842, 'Acts 7:47', 'Acts', 7, 47, 'خو دا سلیمان ؤ چې د خدای دپاره یې کور جوړ کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_47.mp3', '', 1761754199, 1761754199),
(32843, 'Acts 7:48', 'Acts', 7, 48, 'خو خدای تعالی د انسانانو په لاس جوړ شوي کور کې نه اوسیږي. لکه څنګه چې یو پیغمبر وایي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_48.mp3', '', 1761754199, 1761754199),
(32844, 'Acts 7:49', 'Acts', 7, 49, 'اسمان زما تخت دی او ځمکه زما د پښو چوکۍ ده. تاسو به ماته څه ډول کور جوړ کړئ؟ څښتن وایي: او زما د اوسېدلو ځای چېرته دی؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_49.mp3', '', 1761754199, 1761754199),
(32845, 'Acts 7:50', 'Acts', 7, 50, 'ایا دغه ټول شیان ما په خپلو لاسونو باندې پیدا کړي نه دي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_50.mp3', '', 1761754199, 1761754199),
(32846, 'Acts 7:51', 'Acts', 7, 51, 'ای سرزورو خلکو! ستاسو زړونه د کافرو د زړونو په شان دي، د خدای د پیغام اورېدلو ته کاڼه یئ! تاسو تل د خپلو نیکونو په شان د روح القدس په وړاندې ودرېږئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_51.mp3', '', 1761754199, 1761754199),
(32847, 'Acts 7:52', 'Acts', 7, 52, 'ایا داسې کوم پیغمبر شته چې ستاسو نیکونو ځورولی نه وي؟ هغوی هغه پیغمبران هم ووژل چې د هغه د نېک خدمتګار د راتګ پېشګویي یې کړې وه او اوس تاسو د هغه سره خیانت وکړ او هغه مو وواژه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_52.mp3', '', 1761754199, 1761754199),
(32848, 'Acts 7:53', 'Acts', 7, 53, 'تاسو هغه خلک یئ چې شریعت درته د فرښتو په وسیله درورسېد، خو تاسو ورباندې عمل ونه کړ.» د استیفان سنګسارېدل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_53.mp3', '', 1761754199, 1761754199),
(32849, 'Acts 7:54', 'Acts', 7, 54, 'کله چې د شورا غړو د استیفان خبرې واورېدلې، نو ډېر په قهر شول او د قهر له لاسه یې خپل غاښونه وچیچل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_54.mp3', '', 1761754199, 1761754199),
(32850, 'Acts 7:55', 'Acts', 7, 55, 'خو استیفان چې د روح القدس څخه ډک ؤ، اسمان ته په ځیر وکتل او د خدای جلال یې ولیده او عیسی یې ولیده چې د خدای ښي لاس ته ولاړ ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_55.mp3', '', 1761754199, 1761754199),
(32851, 'Acts 7:56', 'Acts', 7, 56, 'هغه وویل: «ګورئ! زه وینم چې د اسمان دروازې خلاصې دي او د انسان زوی د خدای ښي لاس ته ولاړ دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_56.mp3', '', 1761754199, 1761754199),
(32852, 'Acts 7:57', 'Acts', 7, 57, 'د شورا غړو په لوړ اواز سره چیغې ووهلې او خپل غوږونه یې بند کړل او هغوی ټولو په هغه باندې حمله وکړه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_57.mp3', '', 1761754199, 1761754199),
(32853, 'Acts 7:58', 'Acts', 7, 58, 'او هغه یې د ښار څخه دباندې وویست او سنګسار یې کړ. کومو خلکو چې د هغه په خلاف شاهدي ورکړې وه خپلې چپنې وویستلې او د شاوول په نوم د یو ځوان په پښو کې کېښودلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_58.mp3', '', 1761754199, 1761754199),
(32854, 'Acts 7:59', 'Acts', 7, 59, 'کله چې هغوی استیفان سنګساراوه، نو هغه دعا وکړه: «ای څښتنه عیسی! زما روح قبول کړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_59.mp3', '', 1761754199, 1761754199),
(32855, 'Acts 7:60', 'Acts', 7, 60, 'هغه په ګونډو شو او په لوړ اواز یې چیغې ووهلې: «ای څښتنه، هغوی په دې ګناه مه نیسه.» هغه دا خبره وکړه او مړ شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_60.mp3', '', 1761754199, 1761754199),
