(32895, 'John 19:40', 'John', 19, 40, 'هغوی دواړو د عیسی مړی یووړ او د یهودیانو د مړو د ښخولو د مراسمو له مخې یې د خوشبویه تېلو سره په کفن کې تاو کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john19_verse_40.mp3', '', 1761754199, 1761754199),
(32896, 'John 19:41', 'John', 19, 41, 'په کوم ځای کې چې عیسی په صلیب باندې ځړول شوی ؤ هلته یو باغ ؤ او په هغه باغ کې یو نوی قبر ؤ چې تر هغه وخته پورې په کې څوک نه ؤ ښخ شوی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john19_verse_41.mp3', '', 1761754199, 1761754199),
(32897, 'John 19:42', 'John', 19, 42, 'څرنګه چې دا د فسحې د تیارولو ورځ وه او قبر هلته نژدې ؤ، نو هغوی د عیسی مړی هلته ښخ کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john19_verse_42.mp3', '', 1761754199, 1761754199),
(32898, 'Matthew 13:1', 'Matthew', 13, 1, 'په هماغه ورځ عیسی د کور څخه ووت او د بحیرې غاړې ته لاړ او هلته کښېناست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_1.mp3', '', 1761754199, 1761754199),
(32899, 'Matthew 13:2', 'Matthew', 13, 2, 'دومره ډېر خلک ورته راټول شول چې هغه ترې کشتۍ ته وخوت او کښېناست او ټول خلک ورته د بحیرې په غاړه ولاړ وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_2.mp3', '', 1761754199, 1761754199),
(32900, 'Matthew 13:3', 'Matthew', 13, 3, 'هغوی ته یې په مثالونو کې ډېر شیان وویل. هغه وویل: «یو بزګر د تخم شیندلو دپاره پټي ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_3.mp3', '', 1761754199, 1761754199),
(32901, 'Matthew 13:4', 'Matthew', 13, 4, 'کله چې هغه په خپل پټي کې تخم شینده، نو یو څه تخم ترې په لاره کې ولوېد او مرغان راغلل او هغه یې وخوړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_4.mp3', '', 1761754199, 1761754199),
(32902, 'Matthew 13:5', 'Matthew', 13, 5, 'څه تخم په داسې ځمکه ولوېده چې تیږې یې لرلې، نو هغه تخم زر راشین شو، ځکه چې خاوره یې کمه وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_5.mp3', '', 1761754199, 1761754199),
(32903, 'Matthew 13:6', 'Matthew', 13, 6, 'خو کله چې لمر راوخوت نو هغه بوټي وسوځېدل او وچ شول، ځکه چې ریښې یې ژورې نه وې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_6.mp3', '', 1761754199, 1761754199),
(32904, 'Matthew 13:7', 'Matthew', 13, 7, 'څه تخم په اغزو کې ولوېد او اغزي لوی شول او بوټي یې لاندې کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_7.mp3', '', 1761754199, 1761754199),
(32905, 'Matthew 13:8', 'Matthew', 13, 8, 'خو نور تخم په حاصلخیزه خاوره کې ولوېد او حاصل یې ورکړ، ځینو بوټو سل چنده، ځینو شپېته چنده او ځینو دېرش چنده حاصل ورکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_8.mp3', '', 1761754199, 1761754199),
(32906, 'Matthew 13:9', 'Matthew', 13, 9, 'که څوک غوږونه لري، نو هغه دې واوري.» د مثال مقصد (مرقوس ۴‏:‌۱۰‌‏-‌۱۲ او لوقا ۸‏:‌۹، ۱۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_9.mp3', '', 1761754199, 1761754199),
